with Base as (select *, case when location in ('Chiang Mai', 'Berlin') then 'Group A' else 'Other' end as location_group from departments where dept_name = 'HR'), departments_stats as (select case when budget >= 4238000 then 'high' when budget >= 1678000 then 'mid' else 'low' end as budget_bucket, sum(budget) as total_budget, min(budget) as min_budget from Base group by case when budget >= 4238000 then 'high' when budget >= 1678000 then 'mid' else 'low' end) select budget_bucket, total_budget, min_budget from departments_stats
